// FR-066: registerTools wraps every executor in the guard this returns, so no tool author writes one.
export function createCrashGuard(options: CrashGuardOptions): CrashGuard {
  return (name, executor) => async (input, context) => {
    const startedAt = options.clock();
    try {
      return await executor(input, context);
    } catch (thrown: unknown) {
      if (abandoned(context)) throw thrown;
      await reportCrash(options, {name, errorName: errorNameOf(thrown), startedAt}, context);

      return crashResponse(name);
    }
  };
}

---

**Score:** 0.981

## An executor that throws

- It is answered with a `result` naming the tool and saying the call failed, never the thrown message ([validated by: answers an executor that rejects with a result naming the tool, never the thrown message](../../src/orchestration/tools/registry.test.ts#L175)).
- A throw of any shape is answered alike: a string, `undefined`, a plain object, and an object with no prototype, whose message cannot even be turned into a string ([validated by: answers a throw of any shape alike: a string, undefined, a plain object, an object with no prototype](../../src/orchestration/tools/registry.test.ts#L185)).
- The throw is logged once, at `error` under `tool` as `tool executor threw`, with the tool's name, the error's type and its message cut to 500 characters ([validated by: logs a throw once, at error under tool, with the tool name and error type, its message cut to 500 characters](../../src/orchestration/tools/registry.test.ts#L195)).
- A throw after the call's `ToolContext.signal` was aborted for any reason but a timeout, as when its turn is abandoned because the socket closed, is no tool failure: it is logged at `info` instead, once, under `tool` as `tool call abandoned`, with the tool's name and the error's type, and writes no `error` line ([validated by: logs a throw after its signal was aborted, not timed out, at info as tool call abandoned, and no error line](../../src/orchestration/tools/registry.test.ts#L211)).
- A reason that is no error at all, such as a string or `null`, is no timeout either, so a throw after it is logged as abandoned too ([validated by: logs a throw as abandoned after a signal aborted with a reason that is no error, a string or null](../../src/orchestration/tools/registry.test.ts#L225)).
- A throw while the signal is still live, or after it was aborted with a `TimeoutError`, the reason the orchestrator gives at a call's `toolTimeoutMs` deadline, is a failure, logged at `error` as `tool executor threw` ([validated by: keeps a throw at error as tool executor threw while its signal is live and after it timed out](../../src/orchestration/tools/registry.test.ts#L235)).
- The turn goes on to its answer and succeeds: `afterModelResponse` fires and `onError` does not ([validated by: answers a call whose executor threw, and the turn goes on to its answer with afterModelResponse and no onError](../../src/orchestration/chatOrchestrator.test.ts#L770)).

